mapper.select:
SELECT *
  FROM api_key_v2
 WHERE username   = #{username}
   AND domain = #{domain};

SELECT *
  FROM api_key_v2
 WHERE domain = #{domain}
   AND access_key = #{accessKey};

mapper.insert:
INSERT INTO api_key_v2
       (username, principals, domain, access_key, secret
        , created
        , created_by_user_id
        , created_by_realm)
VALUES (#{username}, #{principals}, #{domain}, #{accessKey}, #{secret}
        , #{created}
        , #{createdByUserId}
        , #{createdByRealm});

mapper.delete:
DELETE
  FROM api_key_v2
 WHERE domain = #{domain}
   AND username = #{username}
   AND access_key = #{accessKey};

DELETE
  FROM api_key_v2
 WHERE domain = #{domain}
   AND created < #{expiration};

mapper.select:
SELECT *
  FROM api_key_v2
WHERE domain = #{domain}
ORDER BY created;

SELECT *
  FROM api_key_v2
WHERE created > #{created}
ORDER BY created;

SELECT *
  FROM api_key_v2
WHERE created < #{created}
ORDER BY created;

SELECT *
  FROM api_key_v2
WHERE domain = #{domain}
  AND created < #{created}
ORDER BY created;

SELECT count(*)
  FROM api_key_v2
 WHERE domain = #{domain};

mapper.update:
UPDATE api_key_v2
   SET principals = #{principals}
 WHERE domain = #{domain}
   AND username = #{username}
   AND access_key = #{accessKey};

mapper.select:
SELECT *
  FROM api_key_v2
ORDER BY created
 LIMIT #{limit}
OFFSET #{skip};

  SELECT *
    FROM api_key_v2
   WHERE domain = #{domain}
ORDER BY created
   LIMIT #{limit}
  OFFSET #{skip};

  SELECT *
    FROM api_key_v2
   WHERE domain = #{domain}

     AND username = #{username}

